float vrchHandRevealSample(vec2 uv) {
  vec4 value = vrchSampleSignalTexture(0, clamp(uv, vec2(0.0), vec2(1.0)));
  return max(max(value.r, value.g), max(value.b * uParam_trail, value.a));
}
float vrchHandRevealMask(vec2 uv, float radius) {
  float aspect = iResolution.x / max(iResolution.y, 1.0);
  vec2 x = vec2(radius / max(aspect, 0.01), 0.0);
  vec2 y = vec2(0.0, radius);
  float value = vrchHandRevealSample(uv);
  value = max(value, vrchHandRevealSample(uv + x));
  value = max(value, vrchHandRevealSample(uv - x));
  value = max(value, vrchHandRevealSample(uv + y));
  value = max(value, vrchHandRevealSample(uv - y));
  value = max(value, vrchHandRevealSample(uv + x + y));
  value = max(value, vrchHandRevealSample(uv + x - y));
  value = max(value, vrchHandRevealSample(uv - x + y));
  value = max(value, vrchHandRevealSample(uv - x - y));
  return value;
}
void mainImage(out vec4 fragColor, in vec2 fragCoord) {
  vec2 uv = fragCoord / max(iResolution.xy, vec2(1.0));
  vec4 sourceA = vrchSampleSource0(uv);
  vec4 sourceB = vrchSampleSource1(uv);
  float confidence = vrchReadSignal(0);
  float motion = vrchReadSignal(1);
  vec4 tracking = vrchSampleSignalTexture(0, uv);
  float spread = vrchHandRevealMask(uv, uParam_radius * (1.0 + motion * 0.35));
  float edge0 = mix(0.02, 0.45, clamp(uParam_softness, 0.0, 1.0));
  float mask = smoothstep(edge0, 0.92, spread) * uParam_reveal * confidence;
  vec3 color = mix(sourceA.rgb, sourceB.rgb, clamp(mask, 0.0, 1.0));
  float outline = tracking.a * uParam_outline * confidence;
  color += uParam_outline_color.rgb * outline * 0.45;
  fragColor = vec4(color, mix(sourceA.a, sourceB.a, clamp(mask, 0.0, 1.0)));
}
